const extraFaq:Record<Exclude<Locale,"en">,readonly (readonly [string,string])[]>={
de:[["Warum sind Produktkauf und internationaler Versand getrennt?","LoloBuy beschreibt zwei Stufen: Produkt plus chinesische Inlandslieferung zuerst, internationale Fracht nach Lagereingang und Paketauswahl."],["Wie schätze ich Versandkosten?","Nutze Ziel, aktuelles Gewicht, ehrliche Kategorien und Maße im Live-Rechner. Prüfe tatsächliches und Volumengewicht sowie die Regeln der Route."],["Ist ein konsolidiertes Paket immer günstiger?","Nein. Es kann Grundkosten sparen, aber Volumen, Gewichtsstufe oder Einschränkungen erhöhen. Vergleiche sinnvolle Paketgruppen."],["Kann das Entfernen der Verpackung Kosten senken?","Ja, Gewicht oder Volumen können sinken. Laut öffentlicher Service-Mitteilung kann danach jedoch die Rückgabe oder der Umtausch eingeschränkt sein."],["Sind Lieferzeit und Zollfreigabe garantiert?","Nein. Routenangaben, Tracking und Fotos garantieren weder Termin noch Steuer- oder Zollentscheidung. Live-Regeln und Belege sind maßgeblich."]],
fr:[["Pourquoi l’achat et le fret international sont-ils séparés?","LoloBuy décrit deux étapes: produit et livraison intérieure d’abord, puis fret international après réception et sélection du colis."],["Comment estimer l’expédition?","Utilisez destination, poids récent, catégories exactes et dimensions dans le calculateur actif. Comparez poids réel, volumétrique et règles de la route."],["Un colis consolidé est-il toujours moins cher?","Non. Il peut réduire certains frais mais augmenter volume, tranche de poids ou restrictions. Comparez plusieurs groupements cohérents."],["Retirer l’emballage peut-il réduire le coût?","Oui, mais l’avis public de LoloBuy indique que le retrait de l’emballage peut limiter retour ou échange. Décidez après le QC."],["Délai et dédouanement sont-ils garantis?","Non. Estimation, suivi et photos ne garantissent ni date, ni taxe, ni dédouanement. Vérifiez les règles et conservez les preuves."]],
es:[["¿Por qué compra y envío internacional se pagan por separado?","LoloBuy describe dos fases: producto y entrega nacional primero; transporte internacional tras la llegada al almacén y la selección del paquete."],["¿Cómo estimo el envío?","Usa destino, peso reciente, categorías reales y dimensiones en el estimador activo. Compara peso real, volumétrico y reglas de cada ruta."],["¿Consolidar siempre es más barato?","No. Puede reducir cargos iniciales, pero aumentar volumen, tramo de peso o restricciones. Compara agrupaciones razonables."],["¿Quitar el embalaje reduce el coste?","Puede reducir peso o volumen, pero el aviso público de LoloBuy advierte que puede afectar devoluciones o cambios. Hazlo después del QC."],["¿Se garantizan entrega y aduanas?","No. Estimaciones, seguimiento y fotos no garantizan fecha, impuestos ni despacho. Revisa las reglas vigentes y conserva pruebas."]],
it:[["Perché acquisto e spedizione internazionale sono separati?","LoloBuy descrive due fasi: prodotto e consegna interna prima, trasporto internazionale dopo arrivo in magazzino e scelta del pacco."],["Come stimo la spedizione?","Usa destinazione, peso recente, categorie corrette e dimensioni nel calcolatore attivo. Confronta peso reale, volumetrico e regole della rotta."],["Il consolidamento è sempre più economico?","No. Può ridurre costi iniziali ma aumentare volume, fascia di peso o restrizioni. Confronta gruppi sensati."],["Rimuovere l’imballo riduce il costo?","Può ridurre peso o volume, ma l’avviso pubblico LoloBuy dice che può limitare reso o cambio. Fallo dopo il QC."],["Consegna e dogana sono garantite?","No. Stime, tracking e foto non garantiscono data, tasse o sdoganamento. Controlla le regole attuali e conserva le prove."]],
pt:[["Porque são separados produto e envio internacional?","A LoloBuy descreve duas fases: produto e entrega doméstica primeiro; frete internacional após chegada ao armazém e seleção da encomenda."],["Como estimar o envio?","Use destino, peso recente, categorias verdadeiras e dimensões no estimador ativo. Compare peso real, volumétrico e regras da rota."],["Consolidar é sempre mais barato?","Não. Pode reduzir taxas iniciais, mas aumentar volume, escalão de peso ou restrições. Compare agrupamentos razoáveis."],["Remover embalagem reduz o custo?","Pode reduzir peso ou volume, mas o aviso público da LoloBuy diz que pode limitar devolução ou troca. Decida após o QC."],["Entrega e alfândega são garantidas?","Não. Estimativas, tracking e fotos não garantem data, impostos ou desalfandegamento. Verifique regras atuais e guarde provas."]],
};

export function getPage(locale:Locale,slug:string):LocalPage|undefined{if(slug==="guide")return fullGuidePages[locale];const page=locale==="en"?(basePages as Record<string,LocalPage>)[slug]:translatedPages[locale][slug];if(!page||slug!=="faq"||locale==="en")return page;return {...page,sections:fullTranslatedFaq[locale]??[...page.sections,...extraFaq[locale]]};}

