const homeArrayKeys=["trust","board","strip","feature","cards","cat","prod","evidence","market","workflow","quick","final"] as const;

function requireCompleteText(value:unknown,context:string){
  if(typeof value!=="string"||!value.trim())throw new Error(`Missing localized text: ${context}`);
}

/**
 * Locks every language edition to the English information architecture.
 * Any future translation that drops a page, article, section, card, product,
 * category or market fails the production build instead of publishing a
 * shortened language edition.
 */
export function assertLocaleContentParity(){
  const pageSlugs=Object.keys(basePages);
  const englishArticles=getArticles("en");
  for(const locale of locales){
    const copy=common[locale];
    Object.entries(copy).forEach(([key,value])=>requireCompleteText(value,`${locale}.common.${key}`));
    if(localizedCategories(locale).length!==baseCategories.length)throw new Error(`${locale}: category count changed`);
    if(localizedProducts(locale).length!==baseProducts.length)throw new Error(`${locale}: product count changed`);
    if(localizedMarkets(locale).length!==baseMarkets.length)throw new Error(`${locale}: market count changed`);

    for(const slug of pageSlugs){
      const englishPage=getPage("en",slug);
      const localPage=getPage(locale,slug);
      if(!englishPage||!localPage)throw new Error(`${locale}: missing page ${slug}`);
      requireCompleteText(localPage.eyebrow,`${locale}.${slug}.eyebrow`);
      requireCompleteText(localPage.title,`${locale}.${slug}.title`);
      requireCompleteText(localPage.intro,`${locale}.${slug}.intro`);
      if(localPage.sections.length!==englishPage.sections.length)throw new Error(`${locale}: ${slug} has ${localPage.sections.length} sections; expected ${englishPage.sections.length}`);
      localPage.sections.forEach((section,index)=>section.forEach((value,part)=>requireCompleteText(value,`${locale}.${slug}.section.${index}.${part}`)));
    }

    const localArticles=getArticles(locale);
    if(localArticles.length!==englishArticles.length)throw new Error(`${locale}: SEO article count changed`);
    englishArticles.forEach((englishArticle,index)=>{
      const localArticle=localArticles.find(article=>article.slug===englishArticle.slug);
      if(!localArticle)throw new Error(`${locale}: missing SEO article ${englishArticle.slug}`);
      [localArticle.label,localArticle.date,localArticle.read,localArticle.title,localArticle.excerpt].forEach((value,part)=>requireCompleteText(value,`${locale}.article.${index}.${part}`));
      if(localArticle.sections.length!==englishArticle.sections.length)throw new Error(`${locale}: article ${englishArticle.slug} has ${localArticle.sections.length} sections; expected ${englishArticle.sections.length}`);
      localArticle.sections.forEach((section,sectionIndex)=>section.forEach((value,part)=>requireCompleteText(value,`${locale}.article.${index}.section.${sectionIndex}.${part}`)));
    });

    for(const key of homeArrayKeys){
      if(homeCopy[locale][key].length!==homeCopy.en[key].length)throw new Error(`${locale}: homepage ${key} content count changed`);
      homeCopy[locale][key].forEach((value,index)=>requireCompleteText(value,`${locale}.home.${key}.${index}`));
    }
  }
}

assertLocaleContentParity();
